import React from "react";

export default function Allservices() {
  const services = [
    {
      title: "Multi-Stream Live Events",
      description:
        "Broadcast multiple live streams at once, allowing viewers to switch between perspectives seamlessly.",
      image: "https://source.unsplash.com/600x400/?live,stream",
    },
    {
      title: "Interactive Chat Rooms",
      description:
        "Engage your audience in real-time with chat overlays, reactions, and custom chat rooms for each stream.",
      image: "https://source.unsplash.com/600x400/?chat,technology",
    },
    {
      title: "Agency & Agent Tools",
      description:
        "Manage your streaming teams, assign agents, and monitor live performance all from one dashboard.",
      image: "https://source.unsplash.com/600x400/?camera,studio",
    },
  ];

  return (
    <div className="bg-gradient-to-b from-[#0a0a0f] to-[#111] py-10">
      <div className="max-w-6xl mx-auto px-2 space-y-24">
        {services.map((service, index) => (
          <div
            key={index}
            className={`flex flex-col md:flex-row items-center gap-12 ${
              index % 2 !== 0 ? "md:flex-row-reverse" : ""
            }`}
          >
            {/* Image Section */}
            <div className="md:w-1/2 relative group rounded-2xl overflow-hidden shadow-lg shadow-purple-500/20">
              <img
                src={service.image}
                alt={service.title}
                className="w-full h-[350px] object-cover transform group-hover:scale-110 transition duration-700 ease-out"
              />
              {/* Gradient Overlay */}
              <div className="absolute inset-0 bg-gradient-to-tr from-purple-600/30 to-pink-500/30 opacity-0 group-hover:opacity-100 transition duration-700 ease-out"></div>
            </div>

            {/* Text Section */}
            <div className="md:w-1/2 space-y-6 text-center md:text-left">
              <h2 className="text-3xl md:text-4xl font-bold text-white leading-tight">
                {service.title}
              </h2>
              <p className="text-lg text-gray-300 leading-relaxed">
                {service.description}
              </p>
              <button className="px-8 py-3 bg-gradient-to-r from-purple-500 to-pink-500 text-white font-medium rounded-xl shadow-[0_0_15px_rgba(236,72,153,0.7)] hover:shadow-[0_0_30px_rgba(236,72,153,1)] transform hover:scale-105 transition duration-500 ease-out">
                Learn More
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
